// --- SeekBar component: draggable timeline slider ---
// Uses the same pattern as ZeroRenderControl: native DOM listeners + defaultValue + direct DOM manipulation.
// This guarantees the same responsive drag behavior as the layer sliders.
function SeekBar({
    currentMs,
    durationMs,
    onSeek,
    style
}: {
    currentMs: number;
    durationMs: number;
    onSeek: (ms: number) => void;
    style?: React.CSSProperties;
}) {
    const inputRef = useRef<HTMLInputElement>(null);
    const fillRef = useRef<HTMLDivElement>(null);
    const duration = Math.max(1, durationMs || 1);
    const progress = Math.max(0, Math.min(1, currentMs / duration));

    // Sync fill width directly to DOM when currentMs changes (no re-render of the whole tree)
    useEffect(() => {
        if (fillRef.current) {
            fillRef.current.style.width = `${progress * 100}%`;
        }
        if (inputRef.current) {
            inputRef.current.value = String(currentMs);
        }
    }, [currentMs, progress]);

    // Native DOM listeners — identical pattern to ZeroRenderControl
    useEffect(() => {
        const input = inputRef.current;
        if (!input) return;

        const handleInput = (e: Event) => {
            const val = parseFloat((e.target as HTMLInputElement).value);
            if (!isNaN(val)) {
                // Update fill directly via DOM
                if (fillRef.current) {
                    const pct = Math.max(0, Math.min(100, (val / duration) * 100));
                    fillRef.current.style.width = `${pct}%`;
                }
                // Fire seek via RAF — same as ZeroRenderControl
                requestAnimationFrame(() => {
                    onSeek(val);
                });
            }
        };

        input.addEventListener('input', handleInput);
        input.addEventListener('change', handleInput);

        return () => {
            input.removeEventListener('input', handleInput);
            input.removeEventListener('change', handleInput);
        };
    }, [duration, onSeek]);

    return (
        <div
            style={{
                ...style,
                position: 'relative',
                background: 'rgba(255,255,255,0.12)',
                borderRadius: 999,
                cursor: 'pointer',
                overflow: 'hidden',
                minWidth: 60,
            }}
        >
            <div
                ref={fillRef}
                style={{
                    width: `${progress * 100}%`,
                    height: '100%',
                    background: 'rgba(255, 200, 0, 0.85)',
                    borderRadius: 999,
                    transition: 'none',
                    pointerEvents: 'none',
                    position: 'absolute',
                    top: 0,
                    left: 0,
                }}
            />
            <input
                ref={inputRef}
                type="range"
                min={0}
                max={duration}
                step={1}
                defaultValue={currentMs}
                style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    height: '100%',
                    margin: 0,
                    padding: 0,
                    opacity: 0,
                    cursor: 'pointer',
                    zIndex: 1,
                }}
            />
        </div>
    );
}

/**
 * Script único para arreglar los posts/recursos creados por el autobot
 * que no tienen el tag 'autobotadd' ni source: 'ia'.
 * 
 * Ejecutar: npx ts-node src/scripts/fix-autobot-tags.ts
 * (con el backend corriendo / mongoose conectado)
 */

import mongoose from 'mongoose';
import * as dotenv from 'dotenv';
dotenv.config();

async function main() {
  const uri = process.env.MONGODB_URI || 'mongodb://localhost:27017/artedigital';
  await mongoose.connect(uri);
  console.log('Conectado a MongoDB');

  // Buscar el usuario ADDBOT para identificar sus publicaciones
  const User = mongoose.model('User');
  const botUser = await User.findOne({ username: 'ADDBOT' });
  if (!botUser) {
    console.log('Usuario ADDBOT no encontrado — nada que arreglar.');
    await mongoose.disconnect();
    return;
  }

  const botId = botUser._id;

  // === POSTS ===
  const Post = mongoose.model('Post');
  const postResult = await Post.updateMany(
    { author: botId, tags: { $ne: 'autobotadd' } },
    { 
      $addToSet: { tags: { $each: ['autobotadd', 'noticia'] } },
      $set: { source: 'ia' }
    }
  );
  console.log(`Posts arreglados: ${postResult.modifiedCount} documentos`);

  // === RECURSOS ===
  const Recurso = mongoose.model('Recurso');
  const recursoResult = await Recurso.updateMany(
    { author: botId, tags: { $ne: 'autobotadd' } },
    { 
      $addToSet: { tags: { $each: ['autobotadd', 'digital-art'] } },
      $set: { source: 'ia' }
    }
  );
  console.log(`Recursos arreglados: ${recursoResult.modifiedCount} documentos`);

  console.log('✅ Listo');
  await mongoose.disconnect();
}

main().catch(err => {
  console.error('Error:', err);
  process.exit(1);
});

import { CONFIG } from '../config/environment';

export interface AuthUser {
    username: string;
    displayName: string;
    createdAt: number;
    isAdmin?: boolean;
    sessionIds?: string[];
    activeSessionId?: string;
}

interface AuthResponse {
    success: boolean;
    token?: string;
    user?: AuthUser;
    pendingVerification?: boolean;
    message?: string;
    error?: string;
}

interface MeResponse {
    user: AuthUser;
    error?: string;
}

const TOKEN_KEY = 'volumetric_auth_token';
const USER_KEY = 'volumetric_auth_user';

type AuthChangeCallback = (user: AuthUser | null) => void;

export class AuthManager {
    private static listeners: AuthChangeCallback[] = [];

    static getApiBase(): string {
        return `${CONFIG.AUTH_URL}/api/auth`;
    }

    static getToken(): string | null {
        return localStorage.getItem(TOKEN_KEY);
    }

    static getCachedUser(): AuthUser | null {
        const data = localStorage.getItem(USER_KEY);
        if (!data) return null;
        try {
            return JSON.parse(data);
        } catch {
            return null;
        }
    }

    static isLoggedIn(): boolean {
        return !!this.getToken();
    }

    static onAuthChange(callback: AuthChangeCallback): () => void {
        this.listeners.push(callback);
        return () => {
            this.listeners = this.listeners.filter(cb => cb !== callback);
        };
    }

    private static notifyListeners(user: AuthUser | null): void {
        this.listeners.forEach(cb => cb(user));
    }

    private static saveAuth(token: string, user: AuthUser): void {
        localStorage.setItem(TOKEN_KEY, token);
        localStorage.setItem(USER_KEY, JSON.stringify(user));
        this.notifyListeners(user);
    }

    private static clearAuth(): void {
        localStorage.removeItem(TOKEN_KEY);
        localStorage.removeItem(USER_KEY);
        this.notifyListeners(null);
    }

    static async register(username: string, password: string, displayName?: string): Promise<{ success: boolean; error?: string; user?: AuthUser; pendingVerification?: boolean; message?: string }> {
        try {
            const response = await fetch(`${this.getApiBase()}/register`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password, displayName })
            });

            const data: AuthResponse = await response.json();

            if (!response.ok) {
                return { success: false, error: data.error || 'Registration failed' };
            }

            if (data.pendingVerification || !data.token || !data.user) {
                return {
                    success: true,
                    user: data.user,
                    pendingVerification: true,
                    message: data.message
                };
            }

            this.saveAuth(data.token, data.user);
            return { success: true, user: data.user };
        } catch {
            return { success: false, error: 'Network error. Please try again.' };
        }
    }

    static async login(username: string, password: string): Promise<{ success: boolean; error?: string; user?: AuthUser }> {
        try {
            const response = await fetch(`${this.getApiBase()}/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password })
            });

            const data: AuthResponse = await response.json();

            if (!response.ok) {
                return { success: false, error: data.error || 'Login failed' };
            }

            if (!data.token || !data.user) {
                return { success: false, error: data.error || 'Login failed' };
            }

            this.saveAuth(data.token, data.user);
            return { success: true, user: data.user };
        } catch {
            return { success: false, error: 'Network error. Please try again.' };
        }
    }

    static async logout(): Promise<void> {
        const token = this.getToken();
        if (token) {
            try {
                await fetch(`${this.getApiBase()}/logout`, {
                    method: 'POST',
                    headers: { 'Authorization': `Bearer ${token}` }
                });
            } catch {
                // Ignore network errors on logout
            }
        }
        this.clearAuth();
    }

    static async fetchCurrentUser(): Promise<AuthUser | null> {
        const token = this.getToken();
        if (!token) return null;

        try {
            const response = await fetch(`${this.getApiBase()}/me`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });

            if (!response.ok) {
                this.clearAuth();
                return null;
            }

            const data: MeResponse = await response.json();
            localStorage.setItem(USER_KEY, JSON.stringify(data.user));
            this.notifyListeners(data.user);
            return data.user;
        } catch (err) {
            console.warn('[AuthManager] fetchCurrentUser failed, falling back to cache:', err);
            return this.getCachedUser();
        }
    }

    static async updateProfile(displayName: string): Promise<{ success: boolean; error?: string; user?: AuthUser }> {
        const token = this.getToken();
        if (!token) {
            return { success: false, error: 'Not logged in' };
        }

        try {
            const response = await fetch(`${this.getApiBase()}/profile`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ displayName })
            });

            const data = await response.json();

            if (!response.ok) {
                return { success: false, error: data.error || 'Update failed' };
            }

            localStorage.setItem(USER_KEY, JSON.stringify(data.user));
            this.notifyListeners(data.user);
            return { success: true, user: data.user };
        } catch {
            return { success: false, error: 'Network error. Please try again.' };
        }
    }

    static async getSessions(): Promise<{ success: boolean; error?: string; sessionIds?: string[]; activeSessionId?: string | null }> {
        const token = this.getToken();
        if (!token) {
            return { success: false, error: 'Not logged in' };
        }
        try {
            const response = await fetch(`${this.getApiBase()}/sessions`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await response.json();
            if (!response.ok) {
                return { success: false, error: data.error || 'Failed to load sessions' };
            }
            return { success: true, sessionIds: data.sessionIds || [], activeSessionId: data.activeSessionId ?? null };
        } catch {
            return { success: false, error: 'Network error. Please try again.' };
        }
    }

    static async createSession(sessionId: string): Promise<{ success: boolean; error?: string; sessionIds?: string[]; activeSessionId?: string | null }> {
        const token = this.getToken();
        if (!token) {
            return { success: false, error: 'Not logged in' };
        }
        try {
            const response = await fetch(`${this.getApiBase()}/sessions`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ sessionId })
            });
            const data = await response.json();
            if (!response.ok) {
                return { success: false, error: data.error || 'Failed to create session' };
            }
            return { success: true, sessionIds: data.sessionIds || [], activeSessionId: data.activeSessionId ?? null };
        } catch {
            return { success: false, error: 'Network error. Please try again.' };
        }
    }

    static async setActiveSession(sessionId: string): Promise<{ success: boolean; error?: string; user?: AuthUser }> {
        const token = this.getToken();
        if (!token) {
            return { success: false, error: 'Not logged in' };
        }
        try {
            const response = await fetch(`${this.getApiBase()}/sessions/active`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ sessionId })
            });
            const data = await response.json();
            if (!response.ok) {
                return { success: false, error: data.error || 'Failed to activate session' };
            }

            const cached = this.getCachedUser();
            if (cached && data.user) {
                localStorage.setItem(USER_KEY, JSON.stringify(data.user));
                this.notifyListeners(data.user);
                if (cached.activeSessionId !== data.user.activeSessionId) {
                    window.dispatchEvent(new CustomEvent('volumetric_session_changed', { detail: { sessionId: data.user.activeSessionId } }));
                }
            }

            return { success: true, user: data.user };
        } catch {
            return { success: false, error: 'Network error. Please try again.' };
        }
    }

    static getSessionIdForUser(): string {
        if (CONFIG.isLocal) {
            // Local app: get username from license file (passed via status endpoint potentially)
            // We can just rely on URL params or a default local session
            const urlParams = new URLSearchParams(window.location.search);
            return urlParams.get('session') || urlParams.get('sesion') || 'local_session';
        }

        const user = this.getCachedUser();
        if (user) {
            return user.activeSessionId || user.username;
        }
        const urlParams = new URLSearchParams(window.location.search);
        return urlParams.get('session') || urlParams.get('sesion') || '0';
    }
}
